import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, field } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — экран', () => {
  test('Десктоп: результаты в колонке сбоку от формы #3e4835 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await openCalculator(page);

    const form = await field(page, 'purchasePrice').boundingBox();
    const results = await page.locator('#calc-results-heading').boundingBox();
    expect(form && results, 'форма и результаты на экране').toBeTruthy();
    // RTL: форма справа, результаты слева — по горизонтали не пересекаются.
    expect(results!.x + results!.width, 'результаты левее формы').toBeLessThanOrEqual(form!.x);

    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc, 'нет горизонтальной прокрутки').toBeLessThanOrEqual(widths.win);
  });
});
